package com.example.hesabdari;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.database.*;import java.util.*;
public class MainActivity extends Activity{
 DB db; LinearLayout root,content; int blue=Color.rgb(21,101,192); String currentManager="مدیر سیستم";
 public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);showLogin();}
 TextView tv(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.DKGRAY);t.setPadding(16,12,16,12);return t;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(12,12,12,12);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);TextView h=tv(title,23);h.setTextColor(blue);root.addView(h);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 void showLogin(){base("سامانه یکپارچه حسابداری مدارس");content.addView(tv("ورود مدیر",19));EditText u=new EditText(this);u.setHint("نام کاربری");EditText p=new EditText(this);p.setHint("رمز عبور");p.setInputType(129);content.addView(u);content.addView(p);Button b=btn("ورود");content.addView(b);b.setOnClickListener(v->{Cursor c=db.getReadableDatabase().rawQuery("SELECT name FROM managers WHERE username=? AND password=? AND active=1",new String[]{u.getText().toString(),p.getText().toString()});if(c.moveToFirst()){currentManager=c.getString(0);showHome();}else Toast.makeText(this,"نام کاربری یا رمز عبور نادرست است",Toast.LENGTH_SHORT).show();c.close();});content.addView(tv("ورود اولیه: admin / 1234",13));}
 void showHome(){base("داشبورد");content.addView(tv("خوش آمدید، "+currentManager,18));String[] ms={"🏫 مدارس و مراکز","👤 مدیران","👨‍🎓 دانش‌آموزان","🏦 حساب‌ها و بانک","💳 دریافت‌ها و شهریه","🧾 هزینه‌ها","📊 گزارش مالی","⚙️ تنظیمات"};for(String s:ms){Button b=btn(s);content.addView(b);b.setOnClickListener(v->{String x=((Button)v).getText().toString();if(x.contains("مدارس"))schools();else if(x.contains("مدیران"))managers();else if(x.contains("دانش‌آموز"))students();else if(x.contains("حساب"))accounts();else if(x.contains("شهریه"))transactions("شهریه");else if(x.contains("هزینه"))transactions("هزینه");else if(x.contains("گزارش"))report();else settings();});}}
 void back(){Button b=btn("↩ بازگشت");content.addView(b);b.setOnClickListener(v->showHome());}
 void schools(){base("مدیریت مدارس و مراکز");Button add=btn("➕ افزودن مرکز");content.addView(add);add.setOnClickListener(v->schoolDialog(-1));Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,type,code,active FROM schools ORDER BY id",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout r=new LinearLayout(this);r.addView(tv(c.getString(1)+" | "+c.getString(2)+" | "+c.getString(3)+(c.getInt(4)==1?"":" | غیرفعال"),15),new LinearLayout.LayoutParams(0,-2,1));Button e=btn("ویرایش");r.addView(e);e.setOnClickListener(v->schoolDialog(id));content.addView(r);}c.close();back();}
 void schoolDialog(int id){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=new EditText(this);n.setHint("نام مرکز");EditText type=new EditText(this);type.setHint("نوع مرکز");EditText code=new EditText(this);code.setHint("کد مرکز");CheckBox a=new CheckBox(this);a.setText("فعال");a.setChecked(true);if(id>0){Cursor c=db.getReadableDatabase().rawQuery("SELECT name,type,code,active FROM schools WHERE id=?",new String[]{""+id});if(c.moveToFirst()){n.setText(c.getString(0));type.setText(c.getString(1));code.setText(c.getString(2));a.setChecked(c.getInt(3)==1);}c.close();}l.addView(n);l.addView(type);l.addView(code);l.addView(a);new AlertDialog.Builder(this).setTitle(id<0?"افزودن مرکز":"ویرایش مرکز").setView(l).setPositiveButton("ذخیره",(d,w)->{if(id<0)db.getWritableDatabase().execSQL("INSERT INTO schools(name,type,code,active) VALUES(?,?,?,?)",new Object[]{n.getText().toString(),type.getText().toString(),code.getText().toString(),a.isChecked()?1:0});else db.getWritableDatabase().execSQL("UPDATE schools SET name=?,type=?,code=?,active=? WHERE id=?",new Object[]{n.getText().toString(),type.getText().toString(),code.getText().toString(),a.isChecked()?1:0,id});schools();}).setNegativeButton("انصراف",null).show();}
 void managers(){base("مدیریت مدیران");Button add=btn("➕ افزودن مدیر");content.addView(add);add.setOnClickListener(v->managerDialog(-1));Cursor c=db.getReadableDatabase().rawQuery("SELECT m.id,m.name,m.username,COALESCE(s.name,'-'),m.active FROM managers m LEFT JOIN schools s ON s.id=m.school_id ORDER BY m.id",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout r=new LinearLayout(this);r.addView(tv(c.getString(1)+" | "+c.getString(3)+" | "+c.getString(2)+(c.getInt(4)==1?"":" | غیرفعال"),15),new LinearLayout.LayoutParams(0,-2,1));Button e=btn("ویرایش");r.addView(e);e.setOnClickListener(v->managerDialog(id));content.addView(r);}c.close();back();}
 void managerDialog(int id){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=new EditText(this);n.setHint("نام مدیر");EditText u=new EditText(this);u.setHint("نام کاربری");EditText p=new EditText(this);p.setHint("رمز عبور");CheckBox a=new CheckBox(this);a.setText("فعال");a.setChecked(true);Spinner sp=new Spinner(this);ArrayList<Integer> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();Cursor sc=db.getReadableDatabase().rawQuery("SELECT id,name FROM schools WHERE active=1",null);while(sc.moveToNext()){ids.add(sc.getInt(0));names.add(sc.getString(1));}sc.close();sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));if(id>0){Cursor c=db.getReadableDatabase().rawQuery("SELECT name,username,password,school_id,active FROM managers WHERE id=?",new String[]{""+id});if(c.moveToFirst()){n.setText(c.getString(0));u.setText(c.getString(1));p.setText(c.getString(2));a.setChecked(c.getInt(4)==1);for(int i=0;i<ids.size();i++)if(ids.get(i)==c.getInt(3))sp.setSelection(i);}c.close();}l.addView(n);l.addView(u);l.addView(p);l.addView(sp);l.addView(a);new AlertDialog.Builder(this).setTitle(id<0?"افزودن مدیر":"ویرایش مدیر").setView(l).setPositiveButton("ذخیره",(d,w)->{int sid=ids.isEmpty()?0:ids.get(sp.getSelectedItemPosition());if(id<0)db.getWritableDatabase().execSQL("INSERT INTO managers(name,username,password,school_id,active) VALUES(?,?,?,?,?)",new Object[]{n.getText().toString(),u.getText().toString(),p.getText().toString(),sid,a.isChecked()?1:0});else db.getWritableDatabase().execSQL("UPDATE managers SET name=?,username=?,password=?,school_id=?,active=? WHERE id=?",new Object[]{n.getText().toString(),u.getText().toString(),p.getText().toString(),sid,a.isChecked()?1:0,id});managers();}).setNegativeButton("انصراف",null).show();}
 void students(){base("دانش‌آموزان");EditText q=new EditText(this);q.setHint("جست‌وجوی نام یا کد");content.addView(q);Button add=btn("➕ افزودن دانش‌آموز");content.addView(add);add.setOnClickListener(v->studentDialog(-1));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);Runnable load=()->{list.removeAllViews();String z=q.getText().toString();Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,code,grade,phone FROM students WHERE name LIKE ? OR code LIKE ? ORDER BY id DESC",new String[]{"%"+z+"%","%"+z+"%"});while(c.moveToNext()){int id=c.getInt(0);LinearLayout r=new LinearLayout(this);r.addView(tv(c.getString(1)+" | "+c.getString(2)+" | "+c.getString(3)+" | "+c.getString(4),14),new LinearLayout.LayoutParams(0,-2,1));Button e=btn("ویرایش");r.addView(e);e.setOnClickListener(v->studentDialog(id));list.addView(r);}c.close();};q.setOnEditorActionListener((v,a,e)->{load.run();return false;});load.run();back();}
 void studentDialog(int id){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=new EditText(this);n.setHint("نام و نام خانوادگی");EditText code=new EditText(this);code.setHint("کد دانش‌آموز");EditText grade=new EditText(this);grade.setHint("پایه");EditText phone=new EditText(this);phone.setHint("تلفن");if(id>0){Cursor c=db.getReadableDatabase().rawQuery("SELECT name,code,grade,phone FROM students WHERE id=?",new String[]{""+id});if(c.moveToFirst()){n.setText(c.getString(0));code.setText(c.getString(1));grade.setText(c.getString(2));phone.setText(c.getString(3));}c.close();}l.addView(n);l.addView(code);l.addView(grade);l.addView(phone);new AlertDialog.Builder(this).setTitle(id<0?"افزودن دانش‌آموز":"ویرایش دانش‌آموز").setView(l).setPositiveButton("ذخیره",(d,w)->{if(id<0)db.getWritableDatabase().execSQL("INSERT INTO students(name,code,grade,phone) VALUES(?,?,?,?)",new Object[]{n.getText().toString(),code.getText().toString(),grade.getText().toString(),phone.getText().toString()});else db.getWritableDatabase().execSQL("UPDATE students SET name=?,code=?,grade=?,phone=? WHERE id=?",new Object[]{n.getText().toString(),code.getText().toString(),grade.getText().toString(),phone.getText().toString(),id});students();}).setNegativeButton("انصراف",null).show();}
 void accounts(){base("حساب‌ها و بانک");EditText q=new EditText(this);q.setHint("جست‌وجوی کد یا نام حساب");content.addView(q);Button add=btn("➕ حساب جدید");content.addView(add);add.setOnClickListener(v->accountDialog(-1));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);Cursor c=db.getReadableDatabase().rawQuery("SELECT id,code,name FROM accounts ORDER BY id LIMIT 500",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout r=new LinearLayout(this);r.addView(tv(c.getString(1)+" | "+c.getString(2),14),new LinearLayout.LayoutParams(0,-2,1));Button e=btn("ویرایش");r.addView(e);e.setOnClickListener(v->accountDialog(id));list.addView(r);}c.close();back();}
 void accountDialog(int id){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText code=new EditText(this);code.setHint("کد حساب");EditText name=new EditText(this);name.setHint("نام حساب");if(id>0){Cursor c=db.getReadableDatabase().rawQuery("SELECT code,name FROM accounts WHERE id=?",new String[]{""+id});if(c.moveToFirst()){code.setText(c.getString(0));name.setText(c.getString(1));}c.close();}l.addView(code);l.addView(name);new AlertDialog.Builder(this).setTitle(id<0?"حساب جدید":"ویرایش حساب").setView(l).setPositiveButton("ذخیره",(d,w)->{if(id<0)db.getWritableDatabase().execSQL("INSERT INTO accounts(code,name) VALUES(?,?)",new Object[]{code.getText().toString(),name.getText().toString()});else db.getWritableDatabase().execSQL("UPDATE accounts SET code=?,name=? WHERE id=?",new Object[]{code.getText().toString(),name.getText().toString(),id});accounts();}).setNegativeButton("انصراف",null).show();}
 void transactions(String kind){base(kind.equals("هزینه")?"هزینه‌ها":"دریافت‌ها و شهریه");LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);EditText date=new EditText(this);date.setHint("تاریخ");EditText acc=new EditText(this);acc.setHint("حساب / دانش‌آموز");EditText amount=new EditText(this);amount.setHint("مبلغ");EditText com=new EditText(this);com.setHint("شرح");Button save=btn("ثبت");f.addView(date);f.addView(acc);f.addView(amount);f.addView(com);f.addView(save);content.addView(f);save.setOnClickListener(v->{long a=0;try{a=Long.parseLong(amount.getText().toString().replace(",",""));}catch(Exception e){}db.getWritableDatabase().execSQL("INSERT INTO transactions(date,account,debit,credit,comment,kind) VALUES(?,?,?,?,?,?)",new Object[]{date.getText().toString(),acc.getText().toString(),kind.equals("هزینه")?a:0,kind.equals("شهریه")?a:0,com.getText().toString(),kind});Toast.makeText(this,"ثبت شد",Toast.LENGTH_SHORT).show();transactions(kind);});Cursor c=db.getReadableDatabase().rawQuery("SELECT id,date,account,debit,credit,comment FROM transactions WHERE kind=? ORDER BY id DESC LIMIT 100",new String[]{kind});while(c.moveToNext())content.addView(tv(c.getString(1)+" | "+c.getString(2)+" | "+(c.getLong(3)+c.getLong(4))+"\n"+c.getString(5),14));c.close();back();}
 void report(){base("گزارش مالی");Cursor c=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(debit),0),COALESCE(SUM(credit),0) FROM transactions",null);c.moveToFirst();long d=c.getLong(0),cr=c.getLong(1);c.close();content.addView(tv("جمع بدهکار: "+d,19));content.addView(tv("جمع بستانکار: "+cr,19));content.addView(tv("مانده: "+(cr-d),19));content.addView(tv("داده‌های اولیه از فایل‌های حساب، بانک، شهریه و هزینه وارد شده‌اند.",14));back();}
 void settings(){base("تنظیمات");content.addView(tv("سال تحصیلی و اطلاعات اصلی از دیتابیس محلی خوانده می‌شوند.",16));Button b=btn("خروج از حساب");content.addView(b);b.setOnClickListener(v->showLogin());}
}
